import React, { useEffect, useMemo, useState } from 'react';
import { SOUNDTRACK, SoundtrackTrack, trackById } from '../audio/Soundtrack';
import { audioEngine } from '../audio/VelocityAudioEngine';

interface Props {
  onClose: () => void;
}

/**
 * SOUNDTRACK PLAYER
 * -----------------
 * A road-trip playlist: pick what plays while you drive. Every track here is an
 * original composition generated by the game's own synth engine (see
 * `src/audio/Soundtrack.ts`), so there is nothing to download and nothing
 * licensed to infringe.
 */
export const SoundtrackModal: React.FC<Props> = ({ onClose }) => {
  const [playingId, setPlayingId] = useState<string | null>(() => {
    const current = audioEngine.getNowPlaying();
    return current ? current.id : null;
  });
  const [volume, setVolume] = useState(() => Math.round(audioEngine.getMusicVolume() * 100));
  const [query, setQuery] = useState('');
  const [mood, setMood] = useState<string>('all');

  const moods = useMemo(() => Array.from(new Set(SOUNDTRACK.map((t) => t.genre.split(' / ')[0]))), []);

  const visible = useMemo(() => {
    const q = query.trim().toLowerCase();
    return SOUNDTRACK.filter((t) => {
      if (mood !== 'all' && !t.genre.startsWith(mood)) return false;
      if (!q) return true;
      return (
        t.title.toLowerCase().includes(q) ||
        t.artist.toLowerCase().includes(q) ||
        t.mood.toLowerCase().includes(q) ||
        t.genre.toLowerCase().includes(q)
      );
    });
  }, [query, mood]);

  // Keep the "now playing" marker honest: the player advances by itself at the
  // end of every track, so poll the engine rather than trusting local state.
  useEffect(() => {
    const id = window.setInterval(() => {
      const cur = audioEngine.getNowPlaying();
      setPlayingId(cur ? cur.id : null);
    }, 500);
    return () => window.clearInterval(id);
  }, []);

  const start = (t: SoundtrackTrack) => {
    audioEngine.playTrack(t.id);
    setPlayingId(t.id);
  };

  const toggle = (t: SoundtrackTrack) => {
    if (playingId === t.id) {
      audioEngine.setStation('off');
      setPlayingId(null);
    } else {
      start(t);
    }
  };

  const nowPlaying = playingId ? trackById(playingId) : null;

  return (
    <Overlay onClose={onClose}>
      <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 12 }}>
        <div>
          <div style={{ fontSize: 10, color: '#38bdf8', fontWeight: 900, letterSpacing: 1.6 }}>
            TRILHA SONORA ORIGINAL • VELOCITY STUDIO
          </div>
          <h2 style={{ margin: '4px 0 2px', fontSize: 22 }}>📻 Som da Viagem</h2>
          <div style={{ fontSize: 12, color: '#94a3b8' }}>
            {SOUNDTRACK.length} faixas compostas dentro do jogo — sintetizadas em tempo real, sem
            download e sem direitos autorais de terceiros. Escolha, aperte o play e rode.
          </div>
        </div>
        <button onClick={onClose} style={closeBtn}>
          ✕
        </button>
      </div>

      {/* Transport bar */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 10,
          margin: '14px 0',
          padding: '10px 12px',
          borderRadius: 12,
          background: nowPlaying
            ? `linear-gradient(90deg, ${nowPlaying.accent}33, rgba(255,255,255,0.04))`
            : 'rgba(255,255,255,0.04)',
          border: '1px solid rgba(255,255,255,0.12)',
        }}
      >
        <button
          onClick={() => {
            const id = audioEngine.soundtrackPrevious();
            setPlayingId(id);
          }}
          style={transportBtn}
          title="Faixa anterior"
        >
          ⏮
        </button>
        <button
          onClick={() => {
            if (nowPlaying) {
              audioEngine.setStation('off');
              setPlayingId(null);
            } else {
              start(visible[0] ?? SOUNDTRACK[0]);
            }
          }}
          style={{ ...transportBtn, background: '#ff9500', color: '#000', border: 'none', width: 46, height: 46 }}
          title={nowPlaying ? 'Pausar' : 'Tocar'}
        >
          {nowPlaying ? '⏸' : '▶'}
        </button>
        <button
          onClick={() => {
            const id = audioEngine.soundtrackNext();
            setPlayingId(id);
          }}
          style={transportBtn}
          title="Próxima faixa"
        >
          ⏭
        </button>

        <div style={{ flex: 1, minWidth: 0 }}>
          <div
            style={{
              fontSize: 14,
              fontWeight: 800,
              whiteSpace: 'nowrap',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
            }}
          >
            {nowPlaying ? nowPlaying.title : 'Nada tocando'}
          </div>
          <div style={{ fontSize: 11, color: '#94a3b8' }}>
            {nowPlaying ? `${nowPlaying.artist} • ${nowPlaying.genre} • ${nowPlaying.bpm} BPM • ${nowPlaying.key}` : 'Selecione uma faixa na lista'}
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          <span style={{ fontSize: 12 }}>🔊</span>
          <input
            type="range"
            min={0}
            max={100}
            value={volume}
            onChange={(e) => {
              const v = Number(e.target.value);
              setVolume(v);
              audioEngine.setMusicVolume(v / 100);
            }}
            style={{ width: 96 }}
          />
          <span style={{ fontSize: 11, color: '#94a3b8', width: 30 }}>{volume}%</span>
        </div>
      </div>

      {/* Filters */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 10, flexWrap: 'wrap' }}>
        <input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Buscar faixa, artista, clima..."
          style={{
            flex: 1,
            minWidth: 180,
            background: 'rgba(255,255,255,0.06)',
            border: '1px solid rgba(255,255,255,0.14)',
            borderRadius: 8,
            color: '#fff',
            padding: '7px 10px',
            fontSize: 12,
            outline: 'none',
          }}
        />
        <select
          value={mood}
          onChange={(e) => setMood(e.target.value)}
          style={{
            background: 'rgba(255,255,255,0.06)',
            border: '1px solid rgba(255,255,255,0.14)',
            borderRadius: 8,
            color: '#fff',
            padding: '7px 10px',
            fontSize: 12,
          }}
        >
          <option value="all">Todos os estilos</option>
          {moods.map((m) => (
            <option key={m} value={m}>
              {m}
            </option>
          ))}
        </select>
      </div>

      {/* Track list */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 6, maxHeight: '46vh', overflowY: 'auto', paddingRight: 4 }}>
        {visible.map((t) => {
          const active = playingId === t.id;
          return (
            <div
              key={t.id}
              onClick={() => toggle(t)}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 12,
                padding: '9px 11px',
                borderRadius: 10,
                cursor: 'pointer',
                background: active ? `${t.accent}26` : 'rgba(255,255,255,0.035)',
                border: `1px solid ${active ? t.accent : 'rgba(255,255,255,0.08)'}`,
              }}
            >
              <div
                style={{
                  width: 38,
                  height: 38,
                  borderRadius: 8,
                  flexShrink: 0,
                  background: `linear-gradient(135deg, ${t.accent}, rgba(0,0,0,0.55))`,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontSize: 15,
                  fontWeight: 900,
                  color: '#080b14',
                }}
              >
                {active ? '❚❚' : '▶'}
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 13, fontWeight: 800, display: 'flex', gap: 8, alignItems: 'center' }}>
                  <span style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{t.title}</span>
                  <span style={{ fontSize: 9, color: t.accent, border: `1px solid ${t.accent}66`, borderRadius: 20, padding: '1px 7px', fontWeight: 800 }}>
                    {t.bpm} BPM
                  </span>
                </div>
                <div style={{ fontSize: 11, color: '#94a3b8', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                  {t.genre} • {t.mood} • {t.key} {t.mode === 'major' ? 'maior' : t.mode === 'minor' ? 'menor' : t.mode}
                </div>
                <div style={{ fontSize: 10, color: '#64748b', marginTop: 2 }}>{t.blurb}</div>
              </div>
              <div style={{ width: 74, flexShrink: 0 }}>
                <div style={{ height: 4, borderRadius: 4, background: 'rgba(255,255,255,0.12)', overflow: 'hidden' }}>
                  <div style={{ width: `${Math.round(t.energy * 100)}%`, height: '100%', background: t.accent }} />
                </div>
                <div style={{ fontSize: 9, color: '#64748b', textAlign: 'right', marginTop: 2 }}>
                  energia {Math.round(t.energy * 100)}%
                </div>
              </div>
            </div>
          );
        })}
        {visible.length === 0 && (
          <div style={{ fontSize: 12, color: '#64748b', padding: 14, textAlign: 'center' }}>
            Nenhuma faixa para esse filtro.
          </div>
        )}
      </div>

      <div style={{ fontSize: 10, color: '#475569', marginTop: 10, lineHeight: 1.6 }}>
        Dica: o mix abaixa sozinho quando você pisa fundo (side-chain no motor) e o andamento estica
        levemente com a velocidade — a trilha acompanha a pilotagem em vez de só tocar por cima.
      </div>
    </Overlay>
  );
};

const Overlay: React.FC<{ children: React.ReactNode; onClose: () => void }> = ({ children, onClose }) => (
  <div
    style={{
      position: 'fixed',
      inset: 0,
      zIndex: 60,
      background: 'rgba(3, 6, 14, 0.78)',
      backdropFilter: 'blur(8px)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: 16,
    }}
    onClick={onClose}
  >
    <div
      onClick={(e) => e.stopPropagation()}
      style={{
        width: 'min(760px, 96vw)',
        maxHeight: '92vh',
        overflowY: 'auto',
        background: 'linear-gradient(160deg, #0b1120, #070b14)',
        border: '1px solid rgba(255,255,255,0.14)',
        borderRadius: 16,
        padding: 18,
        color: '#e2e8f0',
        fontFamily: 'inherit',
        boxShadow: '0 30px 80px rgba(0,0,0,0.6)',
      }}
    >
      {children}
    </div>
  </div>
);

const transportBtn: React.CSSProperties = {
  width: 38,
  height: 38,
  borderRadius: 10,
  background: 'rgba(255,255,255,0.07)',
  border: '1px solid rgba(255,255,255,0.16)',
  color: '#fff',
  fontSize: 15,
  cursor: 'pointer',
};

const closeBtn: React.CSSProperties = {
  background: 'rgba(255,255,255,0.07)',
  border: '1px solid rgba(255,255,255,0.16)',
  color: '#fff',
  width: 32,
  height: 32,
  borderRadius: 8,
  cursor: 'pointer',
  fontSize: 14,
};
